<script setup>
import { onMounted, ref } from 'vue'
import { request } from '../../services/request.js'

const loading = ref(true), detailLoading = ref(false), error = ref(''), keyword = ref(''), query = ref(''), page = ref(1)
const result = ref({ items: [], total: 0, page: 1, pageSize: 20 }), detail = ref(null)
function value(row, key) { return row[key] ?? row[key.toUpperCase()] ?? null }
function time(value) { return value ? new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(new Date(value)) : '-' }
function userName(row) { return value(row, 'nickname') || '未设置昵称' }
function userId(row) { return value(row, 'shortId') || value(row, 'userId') || '-' }
function state(row) { const raw = value(row, 'state'); return raw === 'succeeded' ? '成功' : raw === 'failed' ? '失败' : raw === 'sending' || raw === 'reserved' || raw === 'running' ? '处理中' : raw || '-' }
function answer(row) { const text = value(row, 'answer'); return text || (value(row, 'state') === 'succeeded' ? '回答内容不可用' : '本次调用未产生回答') }
function costs(row) { const amount = value(row, 'settledAmount') ?? value(row, 'reservedAmount'); return amount === null ? '-' : `${amount} ${value(row, 'currency') || ''}`.trim() }
async function load(target = page.value) { loading.value = true; error.value = ''; try { result.value = await request(`/admin/ai-audit/questions?page=${target}&pageSize=20&keyword=${encodeURIComponent(query.value)}`); page.value = result.value.page } catch (e) { error.value = e.message || '读取追溯记录失败' } finally { loading.value = false } }
async function showDetail(row) { detailLoading.value = true; error.value = ''; try { detail.value = await request(`/admin/ai-audit/questions/${encodeURIComponent(value(row, 'jobId'))}/detail`) } catch (e) { error.value = e.message || '读取调用详情失败' } finally { detailLoading.value = false } }
function search() { query.value = keyword.value.trim(); page.value = 1; load(1) }
function previous() { if (page.value > 1) load(page.value - 1) }
function next() { if (page.value * result.value.pageSize < result.value.total) load(page.value + 1) }
onMounted(() => load(1))
</script>

<template>
  <section>
    <div class="page-heading"><div><h1>AI 使用追溯</h1><p>按用户和调用记录追溯 AI 使用情况；对话和费用明细仅在查看详情时读取。</p></div></div>
    <div class="notice"><strong>敏感内容访问</strong><span>提问与回答正文仅在点击详情后展示。请仅向确有审计职责的角色授予本菜单权限。</span></div>
    <form class="panel filters" @submit.prevent="search"><input v-model="keyword" maxlength="200" placeholder="搜索昵称、短 ID 或提问内容"/><button class="primary-button" :disabled="loading">{{ loading ? '查询中…' : '查询' }}</button></form>
    <div v-if="error" class="panel error">{{ error }} <button type="button" @click="load(page)">重试</button></div>
    <div v-else class="panel records"><div class="record-summary">共 {{ result.total || 0 }} 条记录 <span>每页 20 条</span></div><div class="table-wrap"><table><thead><tr><th>用户 ID</th><th>用户昵称</th><th>模型</th><th>调用时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="empty">正在读取调用记录…</td></tr><tr v-else v-for="row in result.items" :key="value(row, 'jobId')"><td><code>{{ userId(row) }}</code></td><td>{{ userName(row) }}</td><td>{{ value(row, 'modelName') || value(row, 'modelCode') || '-' }} <small>{{ value(row, 'specification') || '' }}</small></td><td>{{ time(value(row, 'createdAt')) }}</td><td><span :class="['state', value(row, 'state')]">{{ state(row) }}</span></td><td><button class="detail-button" :disabled="detailLoading" @click="showDetail(row)">{{ detailLoading ? '读取中…' : '详情' }}</button></td></tr><tr v-if="!loading && !result.items?.length"><td colspan="6" class="empty">暂无匹配的 AI 调用记录</td></tr></tbody></table></div><div class="pager"><button :disabled="loading || page <= 1" @click="previous">上一页</button><span>第 {{ page }} 页</span><button :disabled="loading || page * result.pageSize >= result.total" @click="next">下一页</button></div></div>
  </section>
  <div v-if="detail" class="modal-mask" @click.self="detail=null"><section class="detail-modal" role="dialog" aria-modal="true" aria-labelledby="audit-detail-title"><header><div><h2 id="audit-detail-title">AI 调用详情</h2><p>{{ userName(detail) }} · {{ userId(detail) }} · {{ time(value(detail, 'createdAt')) }}</p></div><button type="button" aria-label="关闭" @click="detail=null">×</button></header><div class="metrics"><div><span>模型</span><b>{{ value(detail, 'modelName') || value(detail, 'modelCode') || '-' }} {{ value(detail, 'specification') || '' }}</b></div><div><span>Token（输入 / 输出）</span><b>{{ value(detail, 'inputTokens') ?? '-' }} / {{ value(detail, 'outputTokens') ?? '-' }}</b></div><div><span>结算费用</span><b>{{ costs(detail) }}</b></div><div><span>状态</span><b>{{ state(detail) }}</b></div></div><section class="dialog-content"><div><h3>提问原文</h3><p>{{ value(detail, 'question') || '-' }}</p></div><div><h3>回答正文</h3><p>{{ answer(detail) }}</p></div></section><footer><span>请求 ID：<code>{{ value(detail, 'providerRequestId') || '-' }}</code></span><span v-if="value(detail, 'errorCode')">错误：{{ value(detail, 'errorCode') }}</span></footer></section></div>
</template>

<style scoped>
.notice{display:flex;gap:14px;margin:18px 0;padding:14px 16px;border:1px solid #f1d49d;border-radius:10px;color:#76531b;background:#fff9ed;font-size:13px;line-height:1.6}.notice strong{flex:none}.filters{display:flex;gap:10px;padding:16px}.filters input{flex:1;height:42px;padding:0 12px;border:1px solid #d8e0ec;border-radius:8px}.filters button{padding:0 22px}.records{margin-top:18px;padding:0;overflow:hidden}.record-summary{padding:16px 20px;border-bottom:1px solid #e9eef5;color:#34435e;font-weight:700}.record-summary span{margin-left:10px;color:#7d899e;font-weight:400;font-size:12px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:16px;border-bottom:1px solid #e9eef5;text-align:left;color:#263858;font-size:13px}th{color:#71809a;background:#f8faff;font-size:12px}td code{color:#49688f;font-size:12px}td small{display:block;margin-top:4px;color:#7b899f;font-size:11px}.state{display:inline-block;padding:4px 9px;border-radius:999px;color:#56657e;background:#eef2f7;font-size:12px}.state.succeeded{color:#087951;background:#e7f8f1}.state.failed{color:#ad3d45;background:#fff0f1}.detail-button{border:0;color:#126ff4;background:transparent;font-size:13px;font-weight:700}.detail-button:disabled{opacity:.5}.pager{display:flex;justify-content:flex-end;align-items:center;gap:12px;padding:16px 20px}.pager button,.error button{height:32px;padding:0 12px;border:1px solid #cfd9e8;border-radius:7px;color:#286fe4;background:#fff}.pager button:disabled{cursor:not-allowed;opacity:.45}.empty{padding:55px;text-align:center;color:#7b879d}.error{margin-top:18px;padding:18px;color:#a03f46;background:#fff6f6}.error button{margin-left:10px}.detail-modal{box-sizing:border-box;width:min(1040px,calc(100vw - 48px));max-height:90vh;overflow:auto;padding:28px;border-radius:16px;background:#fff;box-shadow:0 24px 80px rgba(15,31,63,.25)}.detail-modal header{display:flex;justify-content:space-between;gap:18px}.detail-modal h2{margin:0;color:#172a4a;font-size:22px}.detail-modal header p{margin:8px 0 0;color:#75839a;font-size:13px}.detail-modal header button{width:34px;height:34px;border:0;border-radius:7px;color:#56657c;background:#f0f4f9;font-size:24px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.metrics>div{padding:12px;border-radius:8px;background:#f6f9fd}.metrics span{display:block;color:#78869d;font-size:11px}.metrics b{display:block;margin-top:6px;color:#263858;font-size:13px;overflow-wrap:anywhere}.dialog-content{display:grid;grid-template-columns:1fr 1fr;gap:14px}.dialog-content>div{min-width:0;padding:16px;border:1px solid #e0e8f3;border-radius:9px}.dialog-content>div:first-child{background:#f7faff}.dialog-content h3{margin:0;color:#43516a;font-size:12px}.dialog-content p{margin:10px 0 0;color:#1f2e4a;font-size:14px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.detail-modal footer{display:flex;gap:20px;margin-top:14px;color:#7b879c;font-size:11px}.detail-modal code{overflow-wrap:anywhere}@media(max-width:900px){.metrics,.dialog-content{grid-template-columns:1fr}.notice{display:block}.notice span{display:block;margin-top:5px}}
</style>
